import hashlib
from bisect import bisect_left

def point(value):
    return int(hashlib.sha256(value.encode()).hexdigest(), 16)

def build_ring(servers):
    return sorted(
        (point(f"{server}:{replica}"), server)
        for server in servers
        for replica in range(3)
    )

def owner(ring, key):
    positions = [position for position, _ in ring]
    index = bisect_left(positions, point(key))
    return ring[index % len(ring)][1]

