def fib(n):
    """Return fib(n) and a tree of every call it made."""
    if n <= 1:
        return n, {"name": f"fib({n}) = {n}"}

    a, left = fib(n - 1)
    b, right = fib(n - 2)
    total = a + b
    node = {"name": f"fib({n}) = {total}", "children": [left, right]}
    return total, node


