import bisect
import hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16) % 360

class Ring:
    def __init__(self, servers, vnodes=3):
        self.points = []  # sorted list of (position, server)
        for s in servers:
            self.add(s, vnodes)

    def add(self, server, vnodes=3):
        for i in range(vnodes):
            bisect.insort(self.points, (h(f"{server}#{i}"), server))

    def owner(self, key):
        pos = h(key)
        i = bisect.bisect_right(self.points, (pos, ""))
        if i == len(self.points):
            i = 0  # wrap around the circle
        return self.points[i][1]

