import hashlib, bisect

V = 150  # virtual nodes per server

class HashRing:
    def __init__(self, servers):
        self.ring = {}          # position -> server
        self.sorted_keys = []   # sorted ring positions
        for s in servers:
            self._add(s)

    def _pos(self, key):
        h = hashlib.md5(key.encode()).digest()
        return int.from_bytes(h[:4], 'big')  # 32-bit position

    def _add(self, server):
        for i in range(V):
            p = self._pos(f"{server}#{i}")
            self.ring[p] = server
            bisect.insort(self.sorted_keys, p)

    def get(self, key):
        p = self._pos(key)
        idx = bisect.bisect_left(self.sorted_keys, p) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

