import hashlib

def position(key):
    return int(hashlib.sha256(key.encode()).hexdigest(), 16) % 100

def assign(keys, servers):
    ring = sorted((token, name) for name, token in servers.items())
    owners = {}
    for key in keys:
        point = position(key)
        owners[key] = next(
            (name for token, name in ring if token >= point),
            ring[0][1],
        )
    return owners

